        connectorProfileCredentials: {
            salesforce: {
                accessToken: salesforceAccessToken,
                refreshToken: salesforceRefreshToken,
                oauthRequest: {
                    authCode: authCode,
                    redirectUri: redirectUri,
                },
            },
        },
    },
});
```

